<template><view class="account-page coupon-page"><view class="coupon-tabs"><button v-for="item in filters" :key="item.id" :class="{selected:filter===item.id}" @click="change(item.id)">{{item.label}}</button></view><view v-if="status==='loading'" class="account-state">正在加载优惠券…</view><view v-else-if="status==='error'" class="account-state"><text>{{error}}</text><button class="secondary" @click="load">重新加载</button></view><EmptyState v-else-if="!items.length" :text="`暂无${filters.find(item=>item.id===filter).label}优惠券`"/><template v-else><view v-for="coupon in items" :key="coupon.id" class="coupon-card" :class="{muted:filter!=='available'}"><view class="coupon-value"><view><text class="currency">¥</text>{{amount(coupon.discountAmount)}}</view><text>{{coupon.thresholdText}}</text></view><view class="coupon-info"><view class="coupon-title">{{coupon.title}}</view><text>{{coupon.validUntilLabel}}</text><text>{{coupon.scopeLabel}}</text></view></view><button v-if="hasMore" class="secondary" :disabled="loadingMore" @click="more">{{loadingMore?'加载中…':'加载更多'}}</button><text v-if="moreError" class="account-error">{{moreError}}</text></template></view></template>
<script setup>
import { ref } from 'vue'
import { onShow,onUnload } from '@dcloudio/uni-app'
import { useAuth } from '../../composables/useAuth'
import { getCoupons } from '../../services/profile'
import EmptyState from '../../components/EmptyState.vue'
useAuth()
const filters=[{id:'available',label:'待使用'},{id:'used',label:'已使用'},{id:'void',label:'已作废'}],filter=ref('available'),items=ref([]),status=ref('loading'),error=ref(''),hasMore=ref(false),loadingMore=ref(false),moreError=ref('')
let epoch=0,cursor=null
const amount=value=>Number.isFinite(value)?(value/100).toFixed(2).replace(/\.00$/,''):'—'
function change(next){if(next!==filter.value){filter.value=next;load()}}
async function load(){const current=++epoch;status.value='loading';items.value=[];loadingMore.value=false;moreError.value='';try{const result=await getCoupons(filter.value);if(current===epoch){items.value=result.items;cursor=result.nextCursor;hasMore.value=result.hasMore===true;status.value='ready'}}catch(reason){if(current===epoch){error.value=reason.message;status.value='error'}}}
async function more(){if(loadingMore.value||!hasMore.value)return;const current=epoch;loadingMore.value=true;try{const result=await getCoupons(filter.value,cursor);if(current===epoch){items.value=[...new Map([...items.value,...result.items].map(item=>[item.id,item])).values()];cursor=result.nextCursor;hasMore.value=result.hasMore===true}}catch(reason){if(current===epoch)moreError.value=reason.message}finally{if(current===epoch)loadingMore.value=false}}
onShow(load);onUnload(()=>{++epoch})
</script>
<style>@import '../../styles/account.css';</style>
<style scoped>.coupon-page{padding-top:0}.coupon-tabs{display:flex;gap:20rpx;background:#343a5b;margin:0 -24rpx 24rpx;padding:12rpx 24rpx 0}.coupon-tabs button{position:relative;flex:1;margin:0;padding:18rpx 0;background:none;color:#a8b5ce;line-height:1.7;font-size:29rpx;border-radius:0}.coupon-tabs .selected{color:#fff}.coupon-tabs .selected:before{content:'';position:absolute;bottom:0;left:calc(50% - 26rpx);width:52rpx;height:5rpx;background:linear-gradient(90deg,#00c5ff,#3451ff);border-radius:5rpx}.coupon-card{display:flex;min-height:184rpx;background:#343a5b;border-radius:18rpx;overflow:hidden;margin-bottom:24rpx}.coupon-card.muted{opacity:.5}.coupon-value{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10rpx;background:linear-gradient(100deg,#0648ff,#009cff);width:184rpx;flex-shrink:0}.coupon-value>view{font-size:56rpx}.currency{font-size:25rpx}.coupon-value>text{font-size:23rpx}.coupon-info{display:flex;flex-direction:column;gap:14rpx;padding:22rpx 18rpx;min-width:0}.coupon-title{font-size:29rpx;color:#fff;overflow-wrap:anywhere}.coupon-info>text{font-size:24rpx;color:#98a7c2;line-height:1.6}</style>
